// The Memory GRAPH page — every memory as a node, every typed edge drawn.
//
// WHY A GRAPH AND NOT ANOTHER LIST. The edges are the whole difference between a memory graph and a
// memory log, and a list can only ever show them as chips on a row — you can read what one memory is
// about, but never which record everything has an opinion about, or which memory nothing can reach.
// Those two questions are the point, and they are only answerable in a picture.
//
// It rides the SHARED `GraphCanvas` (the same Layouts-tier template Glance and the Org designer use),
// so the pan/zoom/world-transform machinery is not reimplemented here — this page brings only its
// world content and its toolbar.
//
// The LAYOUT is deterministic and lives in `lib/memory` where it is unit-tested: columns by kind, most
// -connected first, no physics. A force layout re-arranges on every render and every data change, so a
// node you were reading moves out from under you and the same graph never looks the same twice.
import { useMemo } from "react";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { GraphCanvas, ZoomControls } from "@/shared/ui/layouts/GraphCanvas";
import { useGraphViewport } from "@/shared/ui/layouts/useGraphViewport";
import {
  buildGraph, layoutGraph, NODE_W, NODE_H, KIND_META, type MemoryEntry, type Kind,
} from "@/features/memory/lib/memory";

/** Is this node one of the memory kinds (so it takes a kind colour), or a target stub? */
function isKind(k: string): k is Kind {
  return k in KIND_META;
}

export function MemoryGraphView({ memories, onSelect }: { memories: MemoryEntry[]; onSelect?: (id: string) => void }) {
  const layout = useMemo(() => layoutGraph(buildGraph(memories)), [memories]);
  const vp = useGraphViewport(layout.world);

  return (
    <GraphCanvas
      vp={vp}
      world={layout.world}
      toolbar={
        <Row align="center" gap="sm" className="mem-graph-toolbar">
          <Text as="span" mono className="mem-graph-stat">
            {layout.nodes.length} node{layout.nodes.length === 1 ? "" : "s"} · {layout.edges.length} edge
            {layout.edges.length === 1 ? "" : "s"}
          </Text>
          <ZoomControls vp={vp} />
        </Row>
      }
    >
      {/* Edges first so nodes paint over them. `pointer-events: none` on the layer keeps the canvas
          pan gesture working through the gaps between nodes. */}
      <svg
        className="mem-graph-edges"
        width={layout.world.w}
        height={layout.world.h}
        style={{ position: "absolute", inset: 0, pointerEvents: "none" }}
        aria-hidden="true"
      >
        {layout.edges.map((e, i) => (
          <g key={`${e.from}|${e.rel}|${e.to}|${i}`}>
            <line x1={e.x1} y1={e.y1} x2={e.x2} y2={e.y2} className="mem-edge" />
            {/* The relationship is LABELLED on the edge. `about` and `contradicts` to the same record
                are opposite claims, and an unlabelled line asserts only that they are related. */}
            <text x={(e.x1 + e.x2) / 2} y={(e.y1 + e.y2) / 2 - 4} className="mem-edge-rel" textAnchor="middle">
              {e.rel}
            </text>
          </g>
        ))}
      </svg>

      {layout.nodes.map((n) => (
        <button
          key={n.id}
          type="button"
          data-node
          className="mem-node"
          data-kind={n.kind}
          data-stub={!n.isMemory}
          data-orphan={n.isMemory && n.degree === 0}
          style={{ position: "absolute", left: n.x, top: n.y, width: NODE_W, height: NODE_H }}
          onClick={() => onSelect?.(n.id)}
          title={n.isMemory ? n.label : `${n.kind}: ${n.id}`}
        >
          {/* The type is TEXT on every node, memory or stub. Colour carries no information alone —
              a reader who cannot tell the tones apart must still see which column is which. */}
          <Text as="span" mono className="mem-node-kind">
            {isKind(n.kind) ? KIND_META[n.kind].label.replace(/s$/, "").toLowerCase() : n.kind}
          </Text>
          <Text as="span" className="mem-node-label">{n.label}</Text>
          {n.isMemory && n.degree === 0 && (
            // Named, not merely styled: an edgeless memory is one nothing can traverse to, and that is
            // a state to act on rather than a shade of grey to notice.
            <Text as="span" mono className="mem-node-orphan">no edges</Text>
          )}
        </button>
      ))}
    </GraphCanvas>
  );
}
